def parse_curated():
    """CURATED স্ট্রিং → dict-এর তালিকা।"""
    out = []
    for i, raw in enumerate(CURATED.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        p = _norm_row([x.strip() for x in line.split("|")])
        if len(p) != 19 or p[13] not in "01234" or p[11] not in IUCN_CODES:
            raise ValueError("bad line %d (%d fields): %s" % (i, len(p), line[:90]))
        fix = TAX_FIX.get(p[0])
        cls_id, ord_id, fam_id = p[5], p[6], p[7]
        if fix:
            cls_id, ord_id, fam_id = fix
        out.append({
            "bn_name": p[0], "en_name": p[1], "sci_name": p[2], "authority": p[3],
            "group_id": p[4], "class_id": cls_id, "order_id": ord_id, "family_id": fam_id,
            "region_bn": p[8], "habitat_bn": p[9], "diet_bn": p[10], "iucn": p[11],
            "size_bn": p[12], "venom_level": int(p[13]), "venom_bn": p[14],
            "repro_bn": p[15], "fact_bn": p[16], "extinct_bn": p[17],
            "notes_bn": p[18],
        })
    return out


if __name__ == "__main__":
    rows = parse_curated()
    print("curated species:", len(rows))
    from collections import Counter
    c = Counter(r["group_id"] for r in rows)
    print(dict(c))
    print("extinct:", sum(1 for r in rows if r["iucn"] in ("EX", "EW")))
    for r in rows[:2]:
        print(r["bn_name"], "|", r["sci_name"], "|", r["size_bn"])
